"""Validate portable metadata against the pinned native TenSet TVM runtime.

Developer-only Python 3.8+ tool. The registry must be the trusted synthetic
fixture generated by generate_native.py; native pickle loading executes code.
Normal metadata extraction and the ordinary test suite do not load TVM.
"""

import argparse
import json
import pickle
from pathlib import Path


def reconstruct_savejson(compute_dag):
    """Rebuild SaveJSON for native structural comparison, restoring null spans."""
    if compute_dag["format"] != "tvm-te-expression-graph-v1":
        raise ValueError("unsupported portable expression graph format")
    nodes = [{"type_key": ""}]

    def reference(value):
        return 0 if value is None else value + 1

    for compact in compute_dag["nodes"]:
        kind = compact["type"]
        node = {"type_key": kind}
        if kind == "Array":
            node["data"] = [reference(value) for value in compact["items"]]
        elif kind == "Map":
            entries = compact["entries"]
            if compact["key_kind"] == "string":
                node["keys"] = [key for key, _ in entries]
                node["data"] = [reference(value) for _, value in entries]
            else:
                node["data"] = [reference(value) for pair in entries for value in pair]
        elif kind in {"runtime.String", "Op"}:
            for field in ("repr_str", "repr_b64"):
                if field in compact:
                    node[field] = compact[field]
        else:
            attrs = dict(compact.get("attrs", {}))
            attrs.update(
                {
                    key: str(reference(value))
                    for key, value in compact.get("refs", {}).items()
                }
            )
            if kind.startswith("tir.") or kind in {
                "IntImm",
                "FloatImm",
                "Range",
                "GlobalVar",
            }:
                attrs["span"] = "0"
            node["attrs"] = attrs
        nodes.append(node)
    return {"root": reference(compute_dag["root"]), "nodes": nodes, "b64ndarrays": []}


def validate_tasks(tasks, metadata):
    """Check complete bodies, all initial stages, tensor outputs and loop bounds."""
    import tvm
    from tvm import te

    def assert_reflected_graph_equal(original, restored):
        """Compare native attributes without TE's pointer-only Tensor equality.

        Native reflection supplies reference types independently of the portable
        extractor's schema. This also checks shared references and operation
        attrs, which lowering can legitimately erase.
        """
        from tvm.runtime import _ffi_node_api

        seen, mapping = set(), {}
        stack = [(original, restored)]
        while stack:
            left, right = stack.pop()
            assert type(left) is type(right), (type(left), type(right))
            if left is None or isinstance(left, (str, int, float, bool)):
                assert left == right, (left, right)
                continue
            if isinstance(left, tvm.runtime.DataType):
                assert str(left) == str(right), (left, right)
                continue
            pair = (left.handle.value, right.handle.value)
            assert mapping.setdefault(pair[0], pair[1]) == pair[1], "sharing changed"
            if pair in seen:
                continue
            seen.add(pair)
            if isinstance(left, tvm.ir.container.Array):
                assert len(left) == len(right), "array length changed"
                stack.extend(zip(left, right))
            elif isinstance(left, tvm.ir.container.Map):

                def order(pair):
                    return type(pair[0]).__name__, str(pair[0])

                left_items, right_items = (
                    sorted(left.items(), key=order),
                    sorted(
                        right.items(),
                        key=order,
                    ),
                )
                assert len(left_items) == len(right_items), "map size changed"
                for left_pair, right_pair in zip(left_items, right_items):
                    stack.extend(zip(left_pair, right_pair))
            else:
                names = _ffi_node_api.NodeListAttrNames(left)
                fields = {names(index) for index in range(names(-1))} - {"span"}
                right_names = _ffi_node_api.NodeListAttrNames(right)
                assert fields == {
                    right_names(index) for index in range(right_names(-1))
                } - {"span"}, "native reflected fields changed"
                stack.extend(
                    (getattr(left, field), getattr(right, field)) for field in fields
                )

    expected_keys = {str(task.workload_key) for task in tasks}
    assert set(metadata) == expected_keys, "metadata workload keys differ from registry"
    validated = []
    for task in tasks:
        key = str(task.workload_key)
        portable = metadata[key]
        graph = portable["compute_dag"]
        restored_json = reconstruct_savejson(graph)
        restored = tvm.ir.load_json(json.dumps(restored_json, ensure_ascii=False))
        # TE DataProducerNode::SEqualReduce uses pointer identity in this fork;
        # even native SaveJSON->LoadJSON TE roundtrips fail structural_equal.
        # Independent native reflection checks the complete TE graph, including
        # references and attrs. Lowering eliminates opaque Tensor producers so
        # the official structural_equal can check the resulting TIR semantics.
        assert_reflected_graph_equal(task.compute_dag.tensors, restored)

        def lowered(tensors):
            outputs = [
                tensor.op for tensor in tensors if isinstance(tensor.op, te.ComputeOp)
            ]
            return tvm.lower(te.create_schedule(outputs), list(tensors), name="main")

        tvm.ir.assert_structural_equal(
            lowered(task.compute_dag.tensors), lowered(restored), map_free_vars=True
        )
        tensors = list(task.compute_dag.tensors)
        assert len(portable["tensors"]) == len(tensors), key

        def assert_dimension(native, encoded):
            if isinstance(encoded, dict):
                assert set(encoded) == {"expr_ref"}, (key, encoded)
                expression_graph = dict(restored_json)
                expression_graph["root"] = encoded["expr_ref"] + 1
                expression = tvm.ir.load_json(
                    json.dumps(expression_graph, ensure_ascii=False)
                )
                tvm.ir.assert_structural_equal(native, expression, map_free_vars=True)
            else:
                assert int(native) == encoded, (key, native, encoded)

        for tensor, description in zip(tensors, portable["tensors"]):
            assert str(tensor.name) == description["name"], key
            assert str(tensor.dtype) == description["dtype"], key
            assert len(tensor.shape) == len(description["shape"]), key
            for native, encoded in zip(tensor.shape, description["shape"]):
                assert_dimension(native, encoded)

        operations = list(task.compute_dag.ops)
        assert len(graph["stage_order"]) == len(operations), key
        expected_compute_stages = []
        for stage_id, (operation, operation_ref) in enumerate(
            zip(
                operations,
                graph["stage_order"],
            )
        ):
            compact = graph["nodes"][operation_ref]
            assert compact["type"] == type(operation).__name__, (key, stage_id)
            assert compact["attrs"]["name"] == str(operation.name), (key, stage_id)
            if compact["type"] == "ComputeOp":
                expected_compute_stages.append(stage_id)
        loops = portable["loop_structure"]
        assert [loop["stage_id"] for loop in loops] == expected_compute_stages, key
        assert portable["operation"] == (
            "+".join(str(operations[stage].name) for stage in expected_compute_stages)
            if expected_compute_stages
            else "placeholder"
        ), key
        for loop in loops:
            stage_id = loop["stage_id"]
            operation = operations[stage_id]
            assert loop["operation"] == str(operation.name), key
            assert loop["operation_ref"] == graph["stage_order"][stage_id], key
            for field, attribute in (("spatial", "axis"), ("reduction", "reduce_axis")):
                native_axes = list(getattr(operation, attribute))
                assert len(loop[field]) == len(native_axes), (key, field)
                for native, encoded in zip(native_axes, loop[field]):
                    assert str(native.var.name) == encoded["variable"], key
                    assert_dimension(native.dom.min, encoded["min"])
                    assert_dimension(native.dom.extent, encoded["extent"])
        validated.append(key)
    return validated


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--task-registry",
        required=True,
        help="Trusted native_registry.pkl generated by generate_native.py",
    )
    parser.add_argument(
        "--metadata", required=True, help="Portable export metadata JSON"
    )
    args = parser.parse_args()
    with open(args.task_registry, "rb") as stream:
        tasks = pickle.load(stream)
    metadata = json.loads(Path(args.metadata).read_text(encoding="utf-8"))
    validated = validate_tasks(tasks, metadata)
    print(
        json.dumps(
            {
                "validated_workloads": len(validated),
                "checks": [
                    "native_reflection_complete_expression_graph",
                    "lowered_tir_structural_equal",
                    "initial_stage_order",
                    "tensor_names_shapes_dtypes",
                    "axis_names_minima_extents",
                ],
            }
        )
    )


if __name__ == "__main__":
    main()
